def solve(s):
    # Return list of [character, count] for each consecutive run.
    result = []
    if not s:
        return result
    current_char = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append([current_char, count])
            current_char = ch
            count = 1
    result.append([current_char, count])
    return result

