def solve(nums):
    # Compute next permutation; if none, return sorted list
    n = len(nums)
    if n <= 1:
        return nums[:]
    # Find pivot i where nums[i] < nums[i+1] scanning from right
    i = n - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i == -1:
        return sorted(nums)
    # Find rightmost element greater than nums[i]
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # Create new list to avoid mutating input
    res = nums[:]
    res[i], res[j] = res[j], res[i]
    # Reverse suffix i+1:
    res[i+1:] = reversed(res[i+1:])
    return list(res)

