import bisect

def solve(nums):
    # Return length of longest strictly increasing subsequence
    tails = []  # tails[i] = smallest ending value of an increasing subseq of length i+1
    for x in nums:
        # find location to insert x in tails (strictly increasing => use bisect_left)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

