    """Evaluate Reverse Polish Notation expression.
    Supports +, -, *, / where division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Python's // operator floors toward -inf, so use int(a / b) for truncation toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0
